`,o.jsx(t.h3,{children:"Samrajya – By Alchi"}),`
`,o.jsx(t.p,{children:"Alchi is another Nepali brand making games with cultural and educational twists for Nepali Kids. Samrajya was their first game and is filled with Nepali touches. It's simple enough for kids, but still fun for adults."}),`
`,o.jsxs(t.p,{children:["They have plenty more games worth checking out. See the full collection here: ",o.jsx(t.a,{href:"https://alchi.co",children:"alchi.co"})]}),`
